CREATE TABLE public.song_library (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title text NOT NULL,
  artist text NOT NULL,
  song_key text NOT NULL,
  tempo integer,
  chords text NOT NULL DEFAULT ''
);
GRANT SELECT ON public.song_library TO authenticated;
GRANT ALL ON public.song_library TO service_role;
ALTER TABLE public.song_library ENABLE ROW LEVEL SECURITY;
CREATE POLICY "library readable" ON public.song_library FOR SELECT TO authenticated USING (true);

