CREATE OR REPLACE FUNCTION public.seed_starter_songs()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  INSERT INTO public.songs (user_id, title, artist, song_key, tempo, chords, notes)
  SELECT NEW.id, title, artist, song_key, tempo, chords, 'Starter song — add your lyrics and notes.'
  FROM public.song_library;
  RETURN NEW;
END;
$$;
REVOKE EXECUTE ON FUNCTION public.seed_starter_songs() FROM PUBLIC, anon, authenticated;

CREATE TRIGGER on_auth_user_created_seed_songs
AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.seed_starter_songs();